import React from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { ProspectResult } from '../types';

interface ProspectResultsProps {
  data: ProspectResult;
  onBack: () => void;
}

const ProspectResults: React.FC<ProspectResultsProps> = ({ data, onBack }) => {
  // Helper to deduplicate map links
  const uniqueMaps = data.groundingChunks
    .filter(chunk => chunk.maps?.uri)
    .reduce((acc, current) => {
      const x = acc.find(item => item.maps?.uri === current.maps?.uri);
      if (!x) {
        return acc.concat([current]);
      } else {
        return acc;
      }
    }, [] as typeof data.groundingChunks);

  return (
    <div className="max-w-4xl mx-auto p-4 md:p-6 space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-slate-800">Search Results</h2>
        <button
          onClick={onBack}
          className="px-4 py-2 text-sm font-medium text-slate-600 bg-white border border-slate-300 rounded-md hover:bg-slate-50 transition-colors"
        >
          Modify Search
        </button>
      </div>

      <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-6 prose prose-slate max-w-none prose-table:border prose-td:px-4 prose-td:py-2 prose-th:px-4 prose-th:py-2 prose-th:bg-slate-50">
           {/* We render the raw markdown from Gemini. It usually creates a nice table. */}
           <ReactMarkdown remarkPlugins={[remarkGfm]}>
             {data.text}
           </ReactMarkdown>
        </div>
      </div>

      {uniqueMaps.length > 0 && (
        <div className="space-y-3">
          <h3 className="text-lg font-semibold text-slate-700 flex items-center">
            <svg className="w-5 h-5 mr-2 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
            Verified Locations (Google Maps)
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
            {uniqueMaps.map((chunk, idx) => (
              <a
                key={idx}
                href={chunk.maps?.uri}
                target="_blank"
                rel="noopener noreferrer"
                className="flex flex-col p-3 bg-white border border-slate-200 rounded-md hover:border-green-400 hover:shadow-md transition-all group"
