import React, { useState } from 'react';
import Header from './components/Header';
import SegmentSelector from './components/SegmentSelector';
import ProspectResults from './components/ProspectResults';
import { SearchMode, SearchParams, ProspectResult } from './types';
import { searchProspects } from './services/geminiService';

const App: React.FC = () => {
  const [searchMode, setSearchMode] = useState<SearchMode>('broad');
  const [zipCode, setZipCode] = useState('');
  const [selectedSegment, setSelectedSegment] = useState('');
  const [selectedSubSegment, setSelectedSubSegment] = useState('');

  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<ProspectResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setResults(null);

    const params: SearchParams = {
      mode: searchMode,
      zipCode: searchMode === 'zip' ? zipCode : undefined,
      segment: searchMode === 'segment' ? selectedSegment : undefined,
      subSegment: searchMode === 'segment' ? selectedSubSegment : undefined,
    };

    try {
      const data = await searchProspects(params);
      setResults(data);
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred.");
    } finally {
      setLoading(false);
    }
  };

  const resetSearch = () => {
    setResults(null);
    setError(null);
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header />

      <main className="flex-grow">
        {results ? (
          <ProspectResults data={results} onBack={resetSearch} />
        ) : (
          <div className="max-w-2xl mx-auto p-4 md:p-8 mt-6">
            <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
              <div className="bg-green-600 p-6 text-white">
                <h2 className="text-2xl font-bold">Find Prospects</h2>
                <p className="opacity-90 mt-2">Identify targets in the Baltimore market for Air Care, Drain Care, and Water Treatment solutions.</p>
              </div>

              <div className="p-6 md:p-8">
                <form onSubmit={handleSearch} className="space-y-6">
                  {/* Search Mode Tabs */}
                  <div className="grid grid-cols-3 gap-2 p-1 bg-slate-100 rounded-lg">
                    {(['broad', 'zip', 'segment'] as SearchMode[]).map((mode) => (
                      <button
                        key={mode}
                        type="button"
                        onClick={() => {
                          setSearchMode(mode);
                          setError(null);
                        }}
                        className={`py-2 px-3 rounded-md text-sm font-medium transition-all ${
                          searchMode === mode
                            ? 'bg-white text-green-700 shadow-sm'
                            : 'text-slate-500 hover:text-slate-700'
                        }`}
                      >
                        {mode === 'broad' && 'Broad Search'}
                        {mode === 'zip' && 'By Zip Code'}
                        {mode === 'segment' && 'By Segment'}
                      </button>
                    ))}
                  </div>

                  {/* Dynamic Inputs based on Mode */}
                  <div className="min-h-[120px]">
                    {searchMode === 'broad' && (
                      <div className="p-4 bg-blue-50 border border-blue-100 rounded-md text-blue-800 text-sm">
                        <p className="font-semibold mb-1">Broad Market Search</p>
                        <p>We will search the entire Baltimore metropolitan area for high-value prospects across all major industrial and commercial sectors.</p>
                      </div>
                    )}

                    {searchMode === 'zip' && (
                      <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                          Zip Code (Baltimore Area)
                        </label>
                        <input
                          type="text"
                          required
                          pattern="[0-9]{5}"
                          placeholder="e.g. 21201"
                          value={zipCode}
                          onChange={(e) => setZipCode(e.target.value)}
                          className="w-full rounded-md border-slate-300 shadow-sm focus:border-green-500 focus:ring-green-500 p-2 border"
                        />
                      </div>
                    )}

                    {searchMode === 'segment' && (
                      <SegmentSelector
                        selectedSegment={selectedSegment}
                        selectedSubSegment={selectedSubSegment}
                        onSelectSegment={setSelectedSegment}
                        onSelectSubSegment={setSelectedSubSegment}
                      />
                    )}
                  </div>

                  {/* Error Message */}
                  {error && (
                    <div className="p-3 bg-red-50 text-red-700 text-sm rounded-md border border-red-200">
                      {error}
                    </div>
                  )}

                  {/* Action Button */}
                  <button
                    type="submit"
                    disabled={loading || (searchMode === 'segment' && !selectedSegment)}
                    className={`w-full py-3 px-4 rounded-lg font-bold text-white shadow-md transition-all flex items-center justify-center ${
                      loading
                        ? 'bg-slate-400 cursor-not-allowed'
                        : 'bg-green-600 hover:bg-green-700 hover:shadow-lg'
                    }`}
                  >
                    {loading ? (
                      <>
                        <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Prospecting...
                      </>
                    ) : (
                      'Find Prospects'
                    )}
                  </button>
                </form>
              </div>
            </div>

            <div className="mt-6 text-center text-sm text-slate-500">
              <p>State Industrial Products • Chemical Division</p>
              <p className="mt-1 text-xs">Targeting: Air Care, Drain Care, Wastewater, Water Treatment</p>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { SearchParams, ProspectResult } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const searchProspects = async (params: SearchParams): Promise<ProspectResult> => {
  // Enhanced context with specific product lines for "Likely Services Needed" inference
  const baseContext = `You are a sales prospecting assistant for State Industrial Products (Chemical Division). 
  Your goal is to find valid business prospects in the Baltimore, MD market.

  Focus on businesses that would benefit from State Chemical's primary product lines:
  - Air Care (odor control, scenting)
  - Drain Care (maintenance, blockage prevention)
  - Wastewater (treatment solutions)
  - Water Treatment (cooling towers, boilers, closed loops)
  `;

  let prompt = '';

  if (params.mode === 'broad') {
    prompt = `${baseContext} Search broadly for high-potential commercial, institutional, or industrial prospects in Baltimore, MD. List 10-15 businesses.`;
  } else if (params.mode === 'zip') {
    prompt = `${baseContext} Search for prospects specifically in the zip code ${params.zipCode}, Baltimore area. List all relevant businesses found.`;
  } else if (params.mode === 'segment') {
    const target = params.subSegment ? `${params.subSegment} (${params.segment})` : params.segment;
    prompt = `${baseContext} Search specifically for ${target} businesses in Baltimore, MD. List 10-15 relevant results.`;
  }

  prompt += `

  IMPORTANT:
  1. Return the list in a structured Markdown table with the exact following columns: **Category**, **Business Name**, **Address**, **Phone Number**, **Likely Services Needed**.
  2. **Category**: The market segment (e.g., Healthcare, Manufacturing, Education, Hospitality).
  3. **Likely Services Needed**: Based on the business type, list the most relevant product lines from the list above (Air Care, Drain Care, Wastewater, Water Treatment).
  4. If a phone number is not available, write "N/A".
  5. Ensure the businesses are currently active and located in the Baltimore market.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
        // Note: toolConfig with user location could be added here if we wanted 'nearby' search, 
        // but the user specifically asked for 'Baltimore market', so we rely on the prompt location.
      },
    });

    return {
      text: response.text || "No text response generated.",
      groundingChunks: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
    };
  } catch (error) {
    console.error("Error fetching prospects:", error);
    throw new Error("Failed to fetch prospects. Please check your API key and try again.");
  }
};

