import { GoogleGenAI } from "@google/genai";
import { SearchParams, ProspectResult } from '../types';

// Use a new instance each time to ensure fresh API key context if needed, 
// but here we follow the standard initialization.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const searchProspects = async (params: SearchParams): Promise<ProspectResult> => {
  const baseContext = `You are a high-performance sales prospecting agent for State Industrial Products.
Your mission is to find active, high-potential commercial and industrial businesses.
You MUST use the Google Maps tool to verify the existence and details of these businesses in "${params.location}".

Focus on businesses that need:
- Air Care & Scenting (Hotels, Fitness, Medical)
- Drain & Wastewater Maintenance (Restaurants, Food Processing, Apartments)
- Water Treatment for HVAC/Boilers (Hospitals, Universities, Office Buildings)`;

  let query = '';
  if (params.segment) {
    const target = params.subSegment ? `${params.subSegment} in the ${params.segment} sector` : params.segment;
    query = `Find 15-20 active ${target} businesses in or near ${params.location}.`;
  } else {
    query = `Find 15-20 diverse commercial, institutional, or industrial prospects in or near ${params.location} that would benefit from chemical maintenance services.`;
  }

  const prompt = `
${baseContext}

QUERY: ${query}

OUTPUT INSTRUCTIONS:
1. Return a JSON array of objects.
2. Each object MUST have: "name", "phone", "email", "address", "city", "state", "zip", "notes".
3. Use street address for "address". Split city, state, and zip into their own fields.
4. "notes": Include the business category and specific State Chemical services they likely need based on their business type.
5. If a field like email is unknown, use "".
6. DO NOT include any text before or after the JSON array.
7. Ensure the JSON is valid and complete.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
        // Maps tool does not support responseMimeType: "application/json"
      },
    });

    const responseText = response.text || "";

    // Improved Robust Extraction: Look for the JSON array specifically
    const jsonArrayMatch = responseText.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonArrayMatch) {
      console.error("No JSON array found in response:", responseText);
      // If we got text but no JSON, maybe the model just talked. 
      // Let's try to see if there's any content at all.
      if (responseText.length > 10 && !responseText.includes('[')) {
         throw new Error("The search returned a text response instead of data. Try being more specific with the location.");
      }
      return { prospects: [] };
    }

    try {
      const prospects = JSON.parse(jsonArrayMatch[0]);
      return { prospects };
    } catch (parseError) {
      console.error("JSON Parse Error. Cleaned string was:", jsonArrayMatch[0]);
      throw new Error("Received malformed data from the search engine. Please try again.");
    }
  } catch (error: any) {
    console.error("Gemini Service Error:", error);
    // Handle specific API error messages
    if (error.message?.includes("Requested entity was not found")) {
       throw new Error("API configuration error. Please ensure the Google Maps tool is enabled for your key.");
    }
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
