export const searchProspects = async (params: SearchParams): Promise<ProspectResult> => {
  // Use gemini-2.5-flash as it is optimized for Google Maps grounding tasks.
  const modelName = 'gemini-2.5-flash';

  const baseContext = `You are an expert sales intelligence assistant for State Industrial Products. 
Your goal is to identify high-quality B2B prospects in "${params.location}".

State Industrial Products provides:
- Air Care: Professional scenting and odor control.
- Drain & Wastewater: Solutions for facilities with commercial kitchens or high bathroom usage.
- Water Treatment: Specialized chemistry for boilers and cooling towers.

TARGETS: Focus on commercial, institutional, and industrial facilities.`;

  let userGoal = '';
  if (params.segment) {
    const targetName = params.subSegment || params.segment;
    userGoal = `Find 15-20 active "${targetName}" businesses in the "${params.location}" area.`;
  } else {
    userGoal = `Find a diverse list of 15-20 commercial, institutional, and industrial businesses in "${params.location}" that likely have large facilities requiring maintenance.`;
  }

  // We allow the model to provide a response, but we strictly define the data format we need at the end.
  const prompt = `
${baseContext}

${userGoal}

For each business found, provide:
1. Name
2. Phone number
3. Street Address
4. City, State, and Zip code
5. Notes: Categorize the business and explain why they need State Chemical services (mention specific product lines like Air Care, Drain Care, or Water Treatment).

YOU MUST USE THE GOOGLE MAPS TOOL TO FIND REAL DATA.

Provide the final list as a structured JSON array at the end of your response. 
The JSON objects must have these keys: "name", "phone", "email", "address", "city", "state", "zip", "notes".
Set "email" to "" if not found.

Example JSON structure:
[
  { "name": "...", "phone": "...", "email": "", "address": "...", "city": "...", "state": "...", "zip": "...", "notes": "..." }
]
`;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
        // Note: responseMimeType is not allowed with googleMaps tool.
      },
    });

    const responseText = response.text || "";

    // Use a permissive regex to find the JSON array anywhere in the output.
    // Grounding tools often trigger the model to provide citations or intros/outros.
    const jsonMatch = responseText.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      console.warn("Could not find JSON array in response. Response text was:", responseText);

      // Check for safety filter blocks which result in empty text
      if (!responseText && response.candidates?.[0]) {
        const finishReason = response.candidates[0].finishReason;
        if (finishReason === 'SAFETY') {
          throw new Error("The search was blocked by safety filters. Try a more general search term.");
        }
      }

      return { prospects: [] };
    }

    try {
      // Extract the JSON string and parse it
      const prospects = JSON.parse(jsonMatch[0]);
      if (Array.isArray(prospects)) {
        return { prospects };
      }
      return { prospects: [] };
    } catch (parseError) {
      console.error("Failed to parse extracted JSON content:", jsonMatch[0]);
      throw new Error("The data returned from the search was malformed. Please try the search again.");
    }
  } catch (error: any) {
    console.error("Prospect Search Error:", error);
    if (error.message?.includes("API_KEY")) {
      throw new Error("Missing or invalid API Key.");
    }
    throw error;
  }
};

