import { GoogleGenAI } from "@google/genai";
import { SearchParams, ProspectResult } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const searchProspects = async (params: SearchParams): Promise<ProspectResult> => {
  // Use gemini-2.5-flash for Maps grounding as per documentation.
  const modelName = 'gemini-2.5-flash';

  const systemInstruction = `You are a high-performance B2B prospecting engine for State Industrial Products.
Your absolute priority is to provide a valid JSON array of business leads in the target location.
You MUST use the Google Maps tool to verify business details.
If the Google Maps tool provides limited results, supplement with your internal knowledge of typical businesses in that area that would need industrial cleaning, water treatment, or air care services.

Required Output Format:
A single JSON array containing objects with these EXACT keys: "name", "phone", "email", "address", "city", "state", "zip", "notes".
Notes must explain why they need State Chemical services (Air Care, Drain Maintenance, or Water Treatment).`;

  const userPrompt = `Find 20 commercial/industrial prospects in or near "${params.location}".
${params.segment ? `Focus specifically on: ${params.subSegment || params.segment}.` : 'Focus on facilities like hotels, hospitals, schools, and manufacturing plants.'}

Output the list as a JSON array. 
Even if you include citations or introductory text, the final JSON array must be present and valid.`;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: userPrompt,
      config: {
        systemInstruction,
        tools: [{ googleMaps: {} }],
        temperature: 0.2, // Lower temperature for more consistent formatting
      },
    });

    const responseText = response.text || "";
    console.debug("Model Response:", responseText);

    if (!responseText) {
      // Sometimes if the safety filter or a tool error happens, text is empty.
      // We check candidates.
      if (response.candidates?.[0]?.finishReason === 'SAFETY') {
        throw new Error("The search was restricted for safety reasons. Please try a different location or segment.");
      }
      throw new Error("The search engine returned an empty response. Please try again.");
    }

    // Advanced regex to find the JSON array even if wrapped in markdown blocks or surrounded by text.
    // It looks for the first '[' and the last ']' in the entire string.
    const firstBracket = responseText.indexOf('[');
    const lastBracket = responseText.lastIndexOf(']');

    if (firstBracket === -1 || lastBracket === -1 || lastBracket < firstBracket) {
      console.warn("Raw Response without JSON markers:", responseText);
      throw new Error("No valid data structure found. The search engine may be experiencing high traffic.");
    }

    const jsonString = responseText.substring(firstBracket, lastBracket + 1);

    try {
      const prospects = JSON.parse(jsonString);
      if (Array.isArray(prospects)) {
        // Basic sanitization: Ensure all required fields exist
        const sanitizedProspects = prospects.map(p => ({
          name: p.name || "Unknown Business",
          phone: p.phone || "No Phone Found",
          email: p.email || "",
          address: p.address || "No Address",
          city: p.city || params.location,
          state: p.state || "",
          zip: p.zip || "",
          notes: p.notes || "High potential B2B prospect."
        }));
        return { prospects: sanitizedProspects };
      }
      return { prospects: [] };
    } catch (parseError) {
      console.error("JSON Parsing failed on string:", jsonString);
      throw new Error("The data format was corrupted. Please try a more specific search.");
    }
  } catch (error: any) {
    console.error("Search Error Detail:", error);

    // Specific handling for common API errors
    if (error.message?.includes("API_KEY")) {
      throw new Error("Invalid API Key. Please contact support.");
    }

    throw error;
  }
};

