import { GoogleGenAI } from "@google/genai";
import { SearchParams, ProspectResult, GroundingSource } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const searchProspects = async (params: SearchParams): Promise<ProspectResult> => {
  const modelName = 'gemini-2.5-flash';

  const systemInstruction = `You are a high-performance B2B prospecting engine for State Industrial Products.
Your mission is to provide a valid JSON array of verified business leads.
You MUST use the Google Maps tool to find real-time data for "${params.location}".

State Chemical Services to mention in notes:
- Air Care: Professional scenting (Hotels, Gyms).
- Drain Care: Bacteria-based drain maintenance (Restaurants, Food Prep).
- Water Treatment: Cooling tower/boiler chemicals (Hospitals, Plants).

FORMAT:
You must provide a JSON array containing objects with these keys: "name", "phone", "email", "address", "city", "state", "zip", "notes".
Set unknown fields to "".
"notes" must specify why they are a target for State Chemical.
The JSON must be the only structural data output.`;

  const userPrompt = `Find 15-20 active commercial or industrial businesses in or near "${params.location}".
${params.segment ? `Industry Focus: ${params.subSegment || params.segment}.` : 'Focus on facility managers at hotels, schools, manufacturing plants, and hospitals.'}

Retrieve their contact details and address.
Output the final list as a JSON array.`;

  try {
    const config: any = {
      systemInstruction,
      tools: [{ googleMaps: {} }],
      temperature: 0.1,
    };

    // If user provided latLng via geolocation, use it in the toolConfig
    if (params.latLng) {
      config.toolConfig = {
        retrievalConfig: {
          latLng: params.latLng
        }
      };
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: userPrompt,
      config,
    });

    // Handle potential empty response.text by manually checking parts
    let responseText = "";
    const candidate = response.candidates?.[0];
    if (candidate?.content?.parts) {
      responseText = candidate.content.parts
        .filter(part => part.text)
        .map(part => part.text)
        .join("\n");
    }

    // Extract Grounding Sources as required by rules
    const sourceUrls: GroundingSource[] = [];
    if (candidate?.groundingMetadata?.groundingChunks) {
      candidate.groundingMetadata.groundingChunks.forEach((chunk: any) => {
        if (chunk.maps) {
          sourceUrls.push({
            title: chunk.maps.title || "Map Source",
            uri: chunk.maps.uri
          });
        }
      });
    }

    console.debug("Model Response:", responseText);

    if (!responseText) {
      if (candidate?.finishReason === 'SAFETY') {
        throw new Error("The search was restricted for safety reasons. Try a more general search term.");
      }
      throw new Error("The intelligence engine returned an empty response. Please try a more specific location name (e.g. 'Baltimore, MD').");
    }

    const firstBracket = responseText.indexOf('[');
    const lastBracket = responseText.lastIndexOf(']');

    if (firstBracket === -1 || lastBracket === -1 || lastBracket < firstBracket) {
      throw new Error("No business data could be formatted from the search. Please try again.");
    }

    const jsonString = responseText.substring(firstBracket, lastBracket + 1);

    try {
      const prospects = JSON.parse(jsonString);
      if (Array.isArray(prospects)) {
        const sanitizedProspects = prospects.map(p => ({
          name: p.name || "Unknown Business",
          phone: p.phone || "No Phone",
          email: p.email || "",
          address: p.address || "No Street Address",
          city: p.city || params.location,
          state: p.state || "",
          zip: p.zip || "",
          notes: p.notes || "Identified as a facility requiring chemical maintenance."
        }));
        return { prospects: sanitizedProspects, sourceUrls };
      }
      return { prospects: [], sourceUrls };
    } catch (parseError) {
      console.error("JSON Parse Error:", jsonString);
      throw new Error("The data format was corrupted. Please refine your search area.");
    }
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    if (error.message?.includes("API_KEY")) {
      throw new Error("Invalid API Key configured.");
    }
    throw error;
  }
};

