JSON Format Required:
[
  { "name": "...", "phone": "...", "email": "", "address": "...", "city": "...", "state": "...", "zip": "...", "notes": "..." }
]
"notes" should mention if they need Air Care, Drain Care, or Water Treatment.`;

  const userPrompt = `Search for 15-20 active businesses or facilities in "${locationQuery}".
${params.segment ? `Focus on industry: ${params.subSegment || params.segment}.` : 'Focus on large facilities like apartment complexes, hotels, schools, and industrial sites.'}

