    // Enhanced extraction: check for any text in any part of the first candidate
    let responseText = "";
    const candidate = response.candidates?.[0];

    if (candidate?.content?.parts) {
      // Collect all text parts. Sometimes the model puts text in the second or third part.
      responseText = candidate.content.parts
        .filter(part => part.text)
        .map(part => part.text)
        .join("\n")
        .trim();
    }

    // Capture Grounding Sources (URLs)
