    }

    // Extract JSON from the text response
    const firstBracket = responseText.indexOf('[');
    const lastBracket = responseText.lastIndexOf(']');

    if (firstBracket === -1 || lastBracket === -1 || lastBracket < firstBracket) {
      // Fallback: If the model wrote a list but not JSON, we can't parse it easily.
      throw new Error("The intelligence engine found results but failed to format them for the table. Please try one more time.");
    }

    const jsonString = responseText.substring(firstBracket, lastBracket + 1);

    try {
