const getRegionalContext = (zip: string): string => {
  const zipMap: Record<string, string> = {
    '21222': 'Dundalk/Baltimore, MD (Industrial/Residential Corridor)',
    '21201': 'Downtown Baltimore, MD',
    '21202': 'Baltimore Inner Harbor, MD',
    '21224': 'Canton/Holabird, MD',
  };
  return zipMap[zip] || 'the local area';
};

