  const regionalContext = isZip ? getRegionalContext(cleanLoc) : '';

  // Create a highly descriptive query for the grounding tools
  const locationQuery = isZip 
    ? `Businesses and facilities in zip code ${cleanLoc} (${regionalContext})` 
    : cleanLoc;

