}

const ProspectResults: React.FC<ProspectResultsProps> = ({ data, searchParams, onBack }) => {
  const [copySuccess, setCopySuccess] = useState('');

  const getHeaders = () => ["Prospect Name", "Phone", "Email", "Address", "City", "State", "Zip", "Notes"];

  const handleDownloadCSV = () => {
    const headers = getHeaders();
    const rows = data.prospects.map(p => [
      `"${p.name.replace(/"/g, '""')}"`,
      `"${p.phone.replace(/"/g, '""')}"`,
      `"${p.email.replace(/"/g, '""')}"`,
      `"${p.address.replace(/"/g, '""')}"`,
      `"${p.city.replace(/"/g, '""')}"`,
      `"${p.state.replace(/"/g, '""')}"`,
      `"${p.zip.replace(/"/g, '""')}"`,
      `"${p.notes.replace(/"/g, '""')}"`
    ]);

    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'state_chemical_prospects.csv');
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportPDF = () => {
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF({ orientation: 'landscape' });

    doc.setFontSize(18);
    doc.setTextColor(37, 99, 235);
    doc.text("State Chemical Prospect List", 14, 22);

