                     </div>
                  </div>
                </div>
              </div>
            )}

            {!loading && <HistoryList 
              history={history} 
              onLoadSearch={handleLoadSavedSearch} 
              onDeleteSearch={handleDeleteSavedSearch} 
            />}
          </div>
        )}
      </main>
    </div>
  );
};

